[{"order":1,"type":"heading","text":"Installation, Configuration, and cypress.config.js in Cypress"},{"order":2,"type":"paragraph","text":"This technical tutorial guides you through the process of installing Cypress in a Node.js project, setting up the required directory structure, and configuring the environment using the modern cypress.config.js file."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Node.js version 14 or higher is installed on your system."},{"order":5,"type":"bullet_point","text":"A package manager like npm or yarn is available in your workspace."},{"order":6,"type":"subheading","text":"Step 1: Initializing a Project and Installing Cypress"},{"order":7,"type":"paragraph","text":"First, create a new directory for your project, navigate into it, and initialize a new Node.js project. Then, install Cypress as a development dependency."},{"order":8,"type":"code","text":"mkdir cypress-tutorial
cd cypress-tutorial
npm init -y
npm install cypress --save-dev"},{"order":9,"type":"subheading","text":"Step 2: Opening Cypress for the First Time"},{"order":10,"type":"paragraph","text":"Once installed, you can open the Cypress Test Runner using the npx command. This action generates the default folder structure and configuration file."},{"order":11,"type":"code","text":"npx cypress open"},{"order":12,"type":"paragraph","text":"After running this command, Cypress will prompt you to configure E2E Testing or Component Testing. Select E2E Testing, and Cypress will automatically scaffold files including cypress.config.js."},{"order":13,"type":"subheading","text":"Step 3: Understanding cypress.config.js"},{"order":14,"type":"paragraph","text":"Modern versions of Cypress use cypress.config.js as the central configuration file (replacing the legacy cypress.json). It allows you to define global configurations, environment variables, browser settings, and node event listeners."},{"order":15,"type":"code","text":"const { defineConfig } = require('cypress');

module.exports = defineConfig({
  e2e: {
    baseUrl: 'http://localhost:3000',
    setupNodeEvents(on, config) {
      // Implement node event listeners here
    },
  },
});"},{"order":16,"type":"subheading","text":"Step 4: Configuring Common Options"},{"order":17,"type":"paragraph","text":"You can customize various behaviors by adding properties inside the e2e configuration block. Below is an example of an extended configuration."},{"order":18,"type":"code","text":"const { defineConfig } = require('cypress');

module.exports = defineConfig({
  e2e: {
    baseUrl: 'https://example.cypress.io',
    viewportWidth: 1280,
    viewportHeight: 720,
    defaultCommandTimeout: 10000,
    video: false,
    setupNodeEvents(on, config) {
      // Return the updated config object
      return config;
    },
  },
});"},{"order":19,"type":"subheading","text":"Conclusion"},{"order":20,"type":"paragraph","text":"You have successfully installed Cypress, generated the workspace structure, and learned how to configure your test suite using cypress.config.js. You are now ready to write and execute robust end-to-end tests."}]
